-- Layercake.vw_contact_payment_reconciliation (src/sql/Layercake/Views/Layercake.vw_contact_payment_reconciliation.sql)
/*====================================================================
    Layercake.vw_contact_payment_reconciliation
    Contact payment dataset - per-legal-entity reconciliation to FO
    (DES-001, ADR-002, SPEC-001 REQ-008)
====================================================================*/

/*====================================================================
    One row per legal entity found on either side (FULL OUTER JOIN),
    so an entity missing from one side still shows, with that side 0.

    The FO side is computed straight from synapse_fo.CUSTTRANS, not
    from the rules view, so it is an independent cross-check:
    TRANSTYPE 15, all dates, cancelled payments kept, test accounts
    left out. The test exclusion is NOT EXISTS rather than NOT IN, so
    a NULL apuk_contactnumber in the test list does not drop every
    row, and a duplicated test contact does not multiply rows. Rows
    with a NULL ACCOUNTNUM are in scope (they match no test record).

    Totals keep FO's six decimals (Q-023) and are compared exactly,
    with no rounding. SUM skips NULL amounts, as on both sides alike.
    ISNULL is the outermost expression of each column so the view
    reports them as NOT NULL, as designed.
====================================================================*/
CREATE OR ALTER VIEW Layercake.vw_contact_payment_reconciliation
AS
WITH dataset_side AS (
    SELECT
        fcp.legal_entity,
        COUNT(*) AS row_count,
        CAST(SUM(fcp.amount_paid_gbp) AS decimal(38, 6)) AS amount_paid_gbp
    FROM Layercake.fact_contact_payment AS fcp
    GROUP BY fcp.legal_entity
),

fo_side AS (
    SELECT
        ct.DATAAREAID AS legal_entity,
        COUNT(*) AS row_count,
        CAST(-1 * SUM(ct.AMOUNTMST) AS decimal(38, 6)) AS amount_paid_gbp
    FROM synapse_fo.CUSTTRANS AS ct
    WHERE ct.TRANSTYPE = 15
        AND NOT EXISTS (
            SELECT 1
            FROM CE.tblContact_Test_Records AS tr
            WHERE tr.apuk_contactnumber = ct.ACCOUNTNUM
        )
    GROUP BY ct.DATAAREAID
),

both_sides AS (
    SELECT
        COALESCE(ds.legal_entity, fo.legal_entity) AS legal_entity,
        ISNULL(ds.row_count, 0) AS dataset_row_count,
        ISNULL(fo.row_count, 0) AS fo_row_count,
        ISNULL(ds.amount_paid_gbp, CAST(0 AS decimal(38, 6))) AS dataset_amount_paid_gbp,
        ISNULL(fo.amount_paid_gbp, CAST(0 AS decimal(38, 6))) AS fo_amount_paid_gbp
    FROM dataset_side AS ds
    FULL OUTER JOIN fo_side AS fo
        ON ds.legal_entity = fo.legal_entity
)

SELECT
    -- never NULL: every row comes from at least one side, both keys NOT NULL
    ISNULL(bs.legal_entity, N'') AS legal_entity,
    bs.dataset_row_count,
    bs.fo_row_count,
    bs.dataset_amount_paid_gbp,
    bs.fo_amount_paid_gbp,
    ISNULL(
        CAST(
            CASE
                WHEN bs.dataset_row_count = bs.fo_row_count
                    AND bs.dataset_amount_paid_gbp = bs.fo_amount_paid_gbp
                    THEN 1
                ELSE 0
            END AS bit
        ),
        CAST(0 AS bit)
    ) AS is_reconciled
FROM both_sides AS bs;
GO
